{
  "name": "@x-magpie/opencode",
  "version": "0.5.1",
  "description": "Register a magpie gateway as an opencode model provider: live catalog via provider.transform, openai-compatible streaming.",
  "keywords": [
    "opencode-plugin"
  ],
  "license": "MIT",
  "files": [
    "src/*.ts",
    "README.md",
    "LICENSE"
  ],
  "type": "module",
  "exports": {
    ".": "./src/server.ts",
    "./server": "./src/server.ts",
    "./tui": "./src/tui.ts",
    "./package.json": "./package.json"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "build": "bun run typecheck",
    "test": "bun scripts/smoke.mjs && bun scripts/tui-smoke.mjs",
    "test:e2e": "bun scripts/e2e.mjs"
  },
  "dependencies": {
    "@x-magpie/core": "0.5.1"
  },
  "packageManager": "bun@1.4.4"
}
